        // Blacklist user to meet prelaunch conditions
        vm.prank(owner);
        token.Launch_Settings_01__Blacklist_Bots(user1, false);

        // Verify normal users can't transfer before launch
        vm.startPrank(user1);
        vm.expectRevert();
        token.transfer(user2, 100 ether);
        vm.stopPrank();

        // Verify owner can transfer before launch
        vm.prank(owner);
        token.transfer(address(0xdead), 100_000 ether);
    }

