        vm.startPrank(owner);

        // Calculate minimum limit (0.1% of total supply)
        uint256 minLimit = 1_000; // 1000 tokens (0.001 * 1_000_000)

        // Set exactly at minimum
        token.Contract_SetUp_03__Wallet_Limits(minLimit, minLimit);

        // Try one below minimum for transaction limit
        vm.expectRevert(bytes("E04"));
        token.Contract_SetUp_03__Wallet_Limits(minLimit - 1, minLimit);

        // Try one below minimum for wallet limit
        vm.expectRevert(bytes("E05"));
        token.Contract_SetUp_03__Wallet_Limits(minLimit, minLimit - 1);
        vm.stopPrank();
